#!/usr/bin/env python3
"""Build the human-review register and GitHub index. No sprite edits."""
import pathlib,json,collections,csv,io
D=pathlib.Path(__file__).resolve().parents[1]
M={e['index']:e for e in json.loads((D/'source-map.json').read_text())}
O={int(p[0]):p[1:] for s in (D/'observations.tsv').read_text().splitlines() if (p:=s.split('\t'))}
V={int(p[0]):p[1:] for s in (D/'review.tsv').read_text().splitlines() if (p:=s.split('\t'))}
B=json.loads((D/'batches.json').read_text())
P={31,36,40,49,70,84,86,87,88,99,102,103,104,105,111,112,114,117,119,128,129,130,131,132,133,135,139,142,143,144,145,147,149}
S={15,16,17,22,25,27,28,41,47,48,61,62,71,90,93,98,100,124,131,135}
assert len(P)==33 and len(S)==20 and P|S==set(V) and len(V)==51
assert set(O)==set(range(1,152)) and M[150]['name']=='Enma' and M[150]['species_constant']=='SPECIES_MEWTWO'
records=[]
for n in range(1,152):
    grade,observation=O[n];review=V.get(n)
    records.append({'index':n,'name':M[n]['name'],'classification':grade,'observation':observation,'proportions_list':n in P,'specific_defect_list':n in S,'additional_finding':n not in V and grade!='A','proposal_present':bool(review),'work_done':review[0] if review else 'Aucune modification.','remaining':review[1] if review else ('—' if grade=='A' else 'Diagnostic à confirmer et proposition graphique à préparer.'),'review_status':('incomplete' if review[1]!='—' else 'ready_for_user_review') if review else ('preserve_original' if grade=='A' else 'not_drawn'),'user_approval':'not_requested_yet' if review else 'not_applicable','sources':M[n]['sources'],'compiled':M[n]['compiled']})
(D/'assessment.json').write_text(json.dumps(records,ensure_ascii=False,indent=2)+'\n')
with (D/'assessment.csv').open('w',newline='') as f:
    w=csv.writer(f,lineterminator='\n');w.writerow(['Numéro','Nom','Classe','Problème / observation','Travail réalisé','Reste à faire','Statut','Validation utilisateur'])
    for e in records:w.writerow([f'{e["index"]:03}',e['name'],e['classification'],e['observation'],e['work_done'],e['remaining'],e['review_status'],'Aucune proposition validée'])
counts=collections.Counter(e['classification'] for e in records);states=collections.Counter(e['review_status'] for e in records)
def line(e):
    n=e['index'];batch=next((i for i,g in enumerate(B,1) if n in g),None)
    name=f'{n:03} — {e["name"]}';name=f'[{name}](comparisons/normal/lot-{batch:02}.png)' if batch else name
    label={'incomplete':'**Incomplet / réserves**','ready_for_user_review':'À examiner','preserve_original':'Conserver','not_drawn':'À préparer'}[e['review_status']]
    return f'| {name} | {e["classification"]} | {e["observation"]} | {e["work_done"]} | {e["remaining"]} | {label} |'
table=['| Espèce | Classe | Observation / demande | Travail réalisé | Réserves / reste à faire | Statut |','|---|---|---|---|---|---|']
audit=['# Analyse individuelle des 151 espèces','', 'Classification de départ : A = conserver ; B = correction légère ; C = recomposition ; D = refonte importante. Une classe ne valide pas la proposition produite. Les réserves résultent de la revue des PNG natifs et des comparaisons.','',f'A : {counts["A"]} · B : {counts["B"]} · C : {counts["C"]} · D : {counts["D"]}.','',*table,*map(line,records),'']
(D/'ANALYSE-151.md').write_text('\n'.join(audit).rstrip()+'\n')
readme=['# Refonte artistique des 151 Yo-kai — phase 1','', '**Propositions de travail, sans intégration au jeu et sans validation implicite.** Les comparaisons ci-dessous montrent des PNG natifs 64 × 64, canevas complet, agrandis uniformément **×3** sur damier opaque. Les versions après sont des redessins proposés, pas des sprites approuvés.','',f'**151 espèces / 302 vues originales examinées.** Classement : **{counts["A"]} A**, **{counts["B"]} B**, **{counts["C"]} C**, **{counts["D"]} D**. **51 espèces** des listes prioritaires ont un essai : **{states["ready_for_user_review"]} propositions à examiner** et **{states["incomplete"]} essais incomplets ou non retenus**. Les 33 demandes de proportions et les 20 défauts précis concernent 51 espèces distinctes : 131 et 135 figurent dans les deux listes.','', '**Le résultat artistique est partiel.** Les cases « Après » signalées **ESSAI INCOMPLET** ne signifient pas que le défaut est corrigé. En particulier : les neuf queues de 016 ne sont pas dénombrables avec certitude ; 098 conserve sa face donc le point signalé reste à corriger ; 124 conserve une lecture trop frontale de ses yeux arrière. Les essais 031 et 099 changent trop l’expression ou les proportions pour une correction légère ; 036 ne garantit pas toutes les armes ; 093 n’apporte pas de bénéfice évident. Ne pas intégrer ces essais en l’état.','', '[Analyse complète des 151 espèces](ANALYSE-151.md) · [Tableau CSV](assessment.csv) · [Données JSON et chemins sources](assessment.json) · [Vérifications techniques](technical-validation.json)','', '## Comparaisons normales','', 'Chaque carte contient **Face : Avant / Après**, puis **Dos : Avant / Après**. Numéro, nom, classe et état de la proposition figurent au-dessus. Les familles Castelius 102–105 sont côte à côte sur le lot 5 ; 087–088, 129–130 et 143–144 sont également rapprochés. Aucun original n’est agrandi individuellement ni recadré pour la comparaison.','']
for i,g in enumerate(B,1):
    path=f'comparisons/normal/lot-{i:02}.png';names=', '.join(f'{n:03} {M[n]["name"]}' for n in g)
    readme += [f'### Lot {i} — {len(g)} espèces',names,'',f'[Ouvrir à pleine résolution]({path})','',f'![Comparaison normale avant après lot {i}]({path})','']
readme+=['## Comparaisons shiny','', 'Les mêmes indices de pixels sont affichés avec les **palettes shiny existantes, inchangées**. Aucune nouvelle couleur shiny n’est inventée. Les réserves artistiques des versions normales s’appliquent aussi ici.','']
for i,g in enumerate(B,1):
    path=f'comparisons/shiny/lot-{i:02}.png';readme += [f'### Shiny — lot {i}',f'[Ouvrir à pleine résolution]({path})','',f'![Comparaison shiny avant après lot {i}]({path})','']
readme+=['## Suivi des 51 espèces prioritaires','', 'Toutes les propositions attendent une décision explicite de l’utilisateur. « À examiner » indique une proposition suffisamment cohérente pour la revue, pas une validation artistique définitive. Les essais incomplets sont conservés pour montrer les limites réellement observées.','',*table,*[line(e) for e in records if e['proposal_present']],'','## Constats supplémentaires et originaux préservés','', 'Les **95 espèces classées A** restent entièrement conservées ; les raisons individuelles sont dans [l’analyse complète](ANALYSE-151.md). Les cinq constats autonomes suivants restent **sans proposition dessinée**, et ne sont pas comptés parmi les 51 essais :','',*['- '+f'{e["index"]:03} {e["name"]} — {e["observation"]}' for e in records if e['additional_finding']],'', 'Les petits fragments sur 023, 063, 116 et 137 sont des **résidus possibles**, pas des suppressions autorisées arbitrairement : distinguer un effet volontaire d’un fragment d’atlas. Pour 150, une recomposition des flammes est une piste artistique, pas une erreur technique ni un changement d’identité. **Enma reste 150 / SPECIES_MEWTWO.**','', '## Sources, orientation et pipeline','', 'Les 151 correspondances et chemins exacts sont dans [source-map.json](source-map.json). Les sources actives sont `graphics/yokai/NNN_nom/front.png`, `back.png`, `normal.pal` et `shiny.pal` ; les chemins complets sont consignés par espèce. La compilation produit les tuiles 4bpp/LZ77 et palettes RGB555 référencées par les symboles Pokémon existants dans `src/data/graphics/pokemon.h`. Cette branche de revue ne publie pas l’intégration du jeu restée locale.','', 'Le chemin joueur [BattleLoadPlayerMonSpriteGfx](../../src/battle_gfx_sfx_util.c#L369) charge `gMonBackPicTable`. Le [contrôleur joueur](../../src/battle_controller_player.c#L2105) crée le sprite et lance `gAnims_MonPic`, sans inversion horizontale dans ce chemin normal. Dans [src/data.c](../../src/data.c#L112), le joueur emploie `sAffineAnim_Battler_Normal` avec matrice identité ; les adversaires ont une table distincte avec matrice inversée. Les images de dos sont donc dessinées vers l’adversaire à droite : ne pas leur appliquer le retournement des adversaires. Les effets d’attaque temporaires ne constituent pas la convention du repos.','', 'Les dos réussis 001, 005, 008 et 070 servent de repères pour la lisibilité arrière ; cela n’implique pas qu’un personnage symétrique doive être artificiellement retourné. Les coordonnées et élévations actuelles restent celles du manifeste de [la galerie initiale](../yokai-gallery/source-manifest.json). **Aucune simulation fidèle du terrain ni session d’émulateur n’a été effectuée.** Ces images servent au contrôle des dessins, pas à certifier leur placement en combat.','', 'Les deux archives fournies ont été lues : 84 références puis 67 références. Leur [inventaire avec empreintes](sources/reference-archive-inventory.json) est conservé sans republier les archives. La référence anatomique de Trytik utilisée pour le redessin correspond exactement à celle de l’archive fournie. Les atlas de travail utilisent les sprites réellement intégrés, pas une conversion automatique des illustrations de référence.','', '## Méthode, fichiers de travail et restauration','', '- `proposals/NNN/front.png` et `back.png` : essais indexés 4 bits, 16 entrées de palette maximum dont l’index 0 transparent.','- `proposals/NNN/normal.pal` et `shiny.pal` : copies exactes des palettes existantes. Les redessins sont quantifiés vers ces indices, sans nouvelle palette.','- [sources/originals.zip](sources/originals.zip) : 51 paires avant + palettes, copies originales octet pour octet. Les données originales des 151 espèces restent disponibles dans [l’instantané initial](../yokai-gallery/sources/gba-graphics.zip).','- `sources/reference-*.png`, `proposal-*.png`, `direction-*.txt` : atlas d’entrée, sorties de l’outil de dessin et consignes ; provenance conservée pour éviter de présenter un simple agrandissement comme une refonte.','- [conversion.json](conversion.json) : extraction des nouveaux dessins, limites des cases et coefficient d’échantillonnage **unique par lot**. Seules les marges transparentes des nouveaux atlas sont retirées avant conversion ; aucun ajustement individuel à une taille cible, aucun étirement, aucun original recadré. Les propositions finales possèdent toutes un nouveau canevas 64 × 64.','', 'Les vues à préserver sont recopiées intégralement : faces 017, 022, 025, 027, 028, 041, 047, 048, 061, 062, 090, 093, 098, 100, 111, 124 ; dos 070, 133, 139 et 147. **Sal de bain 113 reste entièrement inchangé.** Aucun fichier de sprite/palette/icône/empreinte/position du jeu n’est remplacé. Une sauvegarde locale complète des ressources intégrées et des cinq fichiers de liaison a aussi été créée avant le travail.','', 'Régénération technique (Python, Pillow et ImageMagick ; aucune nouvelle génération artistique) :','', '```sh','python3 docs/yokai-sprite-rework/scripts/prepare.py','python3 docs/yokai-sprite-rework/scripts/gallery.py','python3 docs/yokai-sprite-rework/scripts/report.py','python3 docs/yokai-sprite-rework/scripts/validate.py','```','', 'Les outils GBA du dépôt sont nécessaires pour le dernier contrôle. La validation convertit les PNG de proposition vers les tuiles 4bpp et LZ77 dans un dossier temporaire et vérifie le retour exact des indices ; elle ne lie pas ces ressources à la ROM. Aucun test de compilation complète après intégration n’est revendiqué : la phase 2 reste bloquée jusqu’à une validation explicite.','', '## Limites et prochaine décision','', 'Les redessins proviennent d’un outil d’édition d’image, puis d’une conversion technique à la palette du jeu. La compatibilité du fichier ne prouve ni l’exactitude anatomique ni la qualité artistique. Les réserves détaillées doivent guider une nouvelle passe de dessin, notamment 016, 031, 036, 061–062, 093, 098–099, 102–105, 112, 124, 128, 131 et 135. Les palettes sont conservées, mais l’affectation sémantique des indices aux nouvelles formes mérite encore la revue visuelle normale/shiny avant intégration.','', 'Valider ou rejeter séparément les propositions par numéro et par vue. Aucune absence de réponse ne déclenche l’intégration. Aucune ROM n’est publiée.','']
(D/'README.md').write_text('\n'.join(readme).rstrip()+'\n')
summary={'examined_species':151,'examined_original_combat_views':302,'classification':dict(counts),'priorities_proportions':len(P),'priorities_specific':len(S),'distinct_priority_species':len(P|S),'proposal_species':51,'proposal_status':dict(states),'new_findings_without_drawing':[e['index'] for e in records if e['additional_finding']],'game_integration':False}
(D/'summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n');print(json.dumps(summary,ensure_ascii=False))
